uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float autop;
uniform float autoSpeed;
uniform float progress;
uniform float scale;
uniform float angle;
uniform float2 position;
uniform float2 stretch;
uniform float alpha;
uniform float hardness;
uniform float blendMode;
uniform float alphaComp;
uniform float2 emitPos;
uniform float2 emitSize;
uniform float emitRound;
uniform float rate;
uniform float velocity;
uniform float velRandom;
uniform float dirTilt;
uniform float spread;
uniform float outwards;
uniform float gravity;
uniform float2 wind;
uniform float drag;
uniform float turb;
uniform float turbSpeed;
uniform float life;
uniform float lifeRandom;
uniform float preRoll;
uniform float loopLen;
uniform float size;
uniform float sizeRandom;
uniform float sizeEnd;
uniform float partStretch;
uniform float feather;
uniform float opacity;
uniform float fadeIn;
uniform float fadeOut;
layout(color) uniform half4 colorStart;
layout(color) uniform half4 colorEnd;
uniform float colorRandom;
uniform float seed;
uniform float gradMap;
uniform float gmTri;
layout(color) uniform half4 gmFg;
layout(color) uniform half4 gmMid;
layout(color) uniform half4 gmBg;
uniform float overdrawOn;
uniform float count;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float2 nmStd(float2 p, float pxs) {
        float z = max(scale * 2.0, 0.002);
        p -= position * pxs;
        p = nmRot(p, -radians(angle));
        return p / (z * max(stretch, float2(0.01)));
    }
    float4 nmGradMap(float4 fx) {
        if (!(gradMap>0.5)) return fx;
        float3 un = fx.a > 0.0001 ? fx.rgb / fx.a : float3(0.0);
        float v = clamp(fx.a * (0.25 + 0.75 * dot(un, float3(0.299, 0.587, 0.114))), 0.0, 1.0);
        float4 pB = float4(gmBg.rgb * gmBg.a, gmBg.a), pM = float4(gmMid.rgb * gmMid.a, gmMid.a), pF = float4(gmFg.rgb * gmFg.a, gmFg.a);
        float4 c = (gmTri>0.5) ? (v < 0.5 ? mix(pB, pM, v * 2.0) : mix(pM, pF, v * 2.0 - 1.0)) : mix(pB, pF, v);
        return c;
    }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * hardness, 0.0, 1.0) * clamp(alpha, 0.0, 1.0);
        float4 b = tex * clamp(alphaComp, 0.0, 1.0);
        float4 o;
        if (int(blendMode) == 0) o = f;
        else if (int(blendMode) == 1) o = float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        else if (int(blendMode) == 2) o = float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        else if (int(blendMode) == 4) o = b + f * (1.0 - b.a);
        else if (int(blendMode) == 5) o = float4(b.rgb + f.rgb, max(b.a, f.a));
        else o = f + b * (1.0 - f.a);
        o = clamp(o, 0.0, 1.0);
        return float4(min(o.rgb, float3(o.a)), o.a);
    }
    float3 hash3(float p) {
        float3 p3 = fract(float3(p) * float3(0.1031, 0.1030, 0.0973));
        p3 += dot(p3, p3.yxz + 33.33);
        return fract((p3.xxy + p3.yzz) * p3.zyx);
    }
    float3 hsv2rgb(float3 c) {
        float3 k = abs(fract(c.xxx + float3(1.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0);
        return c.z * mix(float3(1.0), clamp(k - 1.0, 0.0, 1.0), c.y);
    }
    float eAutoSpeed, eRate, eVelocity, eVelRandom, eSpread, eGravity, eDrag, eTurb, eTurbSpeed, eLife, eLifeRandom;
    float eSize, eSizeRandom, eSizeEnd, eFeather, eOpacity, eFadeIn, eFadeOut, eCount;
    float2 eEmitSize, eEmitPos;
    void fxInit() {
        eAutoSpeed = clamp(autoSpeed, 0.0, 100.0);
        eRate = clamp(rate + 24.0, 0.0, 1000.0);
        eVelocity = clamp(velocity + 960.0, 0.0, 20000.0);
        eVelRandom = clamp(velRandom + 0.3, 0.0, 1.0);
        eSpread = clamp(spread + 25.0, 0.0, 180.0);
        eGravity = clamp(gravity + 768.0, -20000.0, 20000.0);
        eDrag = clamp(drag + 0.3, 0.0, 8.0);
        eTurb = clamp(turb + 38.0, 0.0, 2000.0);
        eTurbSpeed = clamp(turbSpeed + 3.0, 0.0, 20.0);
        eLife = clamp(life + 1800.0, 100.0, 8000.0);
        eLifeRandom = clamp(lifeRandom + 0.3, 0.0, 1.0);
        eSize = clamp(size + 58.0, 1.0, 2000.0);
        eSizeRandom = clamp(sizeRandom + 0.4, 0.0, 1.0);
        eSizeEnd = clamp(sizeEnd + 0.2, 0.0, 3.0);
        eFeather = clamp(feather + 0.6, 0.0, 1.0);
        eOpacity = clamp(opacity + 1.0, 0.0, 1.0);
        eFadeIn = clamp(fadeIn + 0.1, 0.0, 1.0);
        eFadeOut = clamp(fadeOut + 0.5, 0.0, 1.0);
        eCount = clamp(count + 48.0, 1.0, 64.0);
        eEmitSize = max(emitSize + float2(500.0, 0.0), float2(0.0));
        eEmitPos = emitPos + float2(0.0, -370.0);
    }
    float gH;
    float2 flightOffset(float dt, float2 dir, float speed) {
        float dr = max(eDrag, 0.0);
        float damp = (dr * dt < 1e-3) ? dt * (1.0 - 0.5 * dr * dt) : (1.0 - exp(-dr * dt)) / dr;
        return dir * speed * damp + wind / gH * dt + float2(0.0, -eGravity / gH) * (0.5 * dt * dt);
    }
    float2 turbulenceOffset(float age, float kk, float2 phase) {
        if (eTurb <= 0.0) return float2(0.0);
        float w = eTurbSpeed * age;
        float2 wander = float2(sin(w + phase.x) + 0.5 * sin(2.13 * w + phase.y), sin(1.17 * w + phase.y) + 0.5 * sin(2.31 * w + phase.x));
        return eTurb / gH * wander * min(kk * 2.0, 1.0);
    }
    void nmMain() {
        fxInit();
        float2 W = layer;
        float2 uv = amzLayerNorm();
        gH = max(W.y / pxs(), 1.0);
        float2 pc = (uv - 0.5) * W;
        pc = nmStd(float2(pc.x, -pc.y), pxs());
        float2 P = pc / max(W.y, 1.0);
        float uTime = progress + ((autop>0.5) ? time * eAutoSpeed : 0.0);
        float cnt = clamp(floor(eCount + 0.5), 1.0, float(64));
        float lifeMax = max(eLife, 1.0) * 0.001 * (1.0 + eLifeRandom);
        float cyc = max(lifeMax, 1e-3);
        float gens = 0.0;
        float now = uTime + preRoll * 0.001;
        if (loopLen > 0.0) {
            gens = max(floor(loopLen / cyc), 1.0);
            cyc = loopLen / gens;
            now = mod(uTime, loopLen) + loopLen;
        }
        float lattice = cnt / cyc;
        float rateFrac = clamp(eRate / lattice, 0.0, 1.0);
        float vel0 = eVelocity / gH;
        float4 acc = float4(0.0);
        for (int i = 0; i < 64; i++) {
            if (float(i) >= cnt) break;
            float idx = float(i);
            float since = now - idx / lattice;
            if (since < 0.0) continue;
            float generation = floor(since / cyc);
            float age = since - generation * cyc;
            float genId = gens > 0.0 ? mod(generation, gens) : generation;
            float sid = idx * 1.7 + genId * 91.7 + seed * 13.31;
            float3 r5 = hash3(sid + 191.3);
            if (r5.x >= rateFrac) continue;
            float3 r1 = hash3(sid);
            float lf = max(max(eLife, 1.0) * 0.001 * (1.0 + (r1.x - 0.5) * 2.0 * eLifeRandom), 1e-3);
            float k = age / lf;
            if (k > 1.0) continue;
            float3 r2 = hash3(sid + 37.13);
            float3 r3 = hash3(sid + 71.77);
            float3 r4 = hash3(sid + 113.7);
            float2 halfSize = eEmitSize / gH * 0.5;
            float2 unit = r2.xy * 2.0 - 1.0;
            if ((emitRound>0.5)) {
                float rr = sqrt(max(r2.z, 0.0));
                float ph = 6.2831853 * r2.x;
                unit = float2(cos(ph), sin(ph)) * rr;
            }
            float2 offs = unit * halfSize;
            float a = radians(dirTilt + (r1.y * 2.0 - 1.0) * clamp(eSpread, 0.0, 180.0));
            float2 dir = float2(sin(a), cos(a));
            float offLen = length(offs);
            if (outwards > 0.001 && offLen > 1e-4) dir = normalize(mix(dir, offs / offLen, clamp(outwards, 0.0, 1.0)));
            float speed = vel0 * max(0.0, 1.0 + (r4.x - 0.5) * 2.0 * eVelRandom);
            float2 phase = r3.xy * 6.2831853;
            float2 emitter = eEmitPos / gH + offs;
            float2 amzLocal_pos = emitter + flightOffset(age, dir, speed) + turbulenceOffset(age, k, phase);
            float sz = max(eSize / gH * max(0.05, 1.0 + (r4.y - 0.5) * 2.0 * eSizeRandom) * mix(1.0, eSizeEnd, k), 1e-5);
            float2 axisV = float2(0.0, 1.0);
            float szV = sz;
            if (partStretch > 0.0) {
                float2 vel = dir * speed * exp(-max(eDrag, 0.0) * age) + wind / gH + float2(0.0, -eGravity / gH) * age;
                float vlen = length(vel);
                if (vlen > 1e-3) {
                    axisV = vel / vlen;
                    szV = sz * clamp(1.0 + partStretch * vlen / max(vel0, 1e-3), 1.0, 1.0 + partStretch * 6.0);
                }
            }
            float2 axisU = float2(-axisV.y, axisV.x);
            float2 d = P - amzLocal_pos;
            float mx = max(sz, szV);
            if (dot(d, d) > 0.25 * mx * mx) continue;
            float2 corner = float2(dot(d, axisU) / (sz * 0.5), dot(d, axisV) / (szV * 0.5));
            float dist = length(corner);
            if (dist >= 1.0) continue;
            float fIn = eFadeIn <= 0.0 ? 1.0 : smoothstep(0.0, eFadeIn, k);
            float fOut = eFadeOut <= 0.0 ? 1.0 : 1.0 - smoothstep(1.0 - eFadeOut, 1.0, k);
            float3 color = mix(colorStart.rgb, colorEnd.rgb, k);
            if (colorRandom > 0.0) color = mix(color, hsv2rgb(float3(r4.z, 0.85, 1.0)), clamp(colorRandom, 0.0, 1.0));
            float core = clamp(1.0 - eFeather, 0.0, 0.95);
            float al = eOpacity * fIn * fOut * (1.0 - smoothstep(core, 1.0, dist));
            float4 src = float4(color * al, al);
            acc = src + acc * (1.0 - src.a);
        }
        float2 ins = step(float2(0.0), uv) * step(uv, float2(1.0));
        float4 base = amzTexture(0, l2s(clamp(uv, 0.0, 1.0))) * (ins.x * ins.y);
        amzOutput = nmBlend(base, nmGradMap(acc));
    }
    void amzRender() {
        nmMain();
        if (!(overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
